use std::alloc::{GlobalAlloc, Layout, System};
use std::collections::HashMap;
use std::sync::Arc;
use std::sync::atomic::{AtomicBool, AtomicU64, Ordering::Relaxed};
use kujo::interpreter::BindingKind;
static TRACK: AtomicBool = AtomicBool::new(false);
static REQUESTS: AtomicU64 = AtomicU64::new(0);
static BYTES: AtomicU64 = AtomicU64::new(0);
struct Counter;
unsafe impl GlobalAlloc for Counter {
    unsafe fn alloc(&self, layout: Layout) -> *mut u8 {
        if TRACK.load(Relaxed) { REQUESTS.fetch_add(1, Relaxed); BYTES.fetch_add(layout.size() as u64, Relaxed); }
        unsafe { System.alloc(layout) }
    }
    unsafe fn dealloc(&self, p: *mut u8, layout: Layout) { unsafe { System.dealloc(p, layout) } }
    unsafe fn realloc(&self, p: *mut u8, old: Layout, size: usize) -> *mut u8 {
        if TRACK.load(Relaxed) { REQUESTS.fetch_add(1, Relaxed); BYTES.fetch_add(size as u64, Relaxed); }
        unsafe { System.realloc(p, old, size) }
    }
}
#[global_allocator] static ALLOCATOR: Counter = Counter;
fn measure<T>(make: impl FnOnce() -> T) -> (T, u64, u64) {
    REQUESTS.store(0, Relaxed); BYTES.store(0, Relaxed); TRACK.store(true, Relaxed);
    let result = make();
    TRACK.store(false, Relaxed);
    (result, REQUESTS.load(Relaxed), BYTES.load(Relaxed))
}
fn main() {
    println!("width,name_length,phase,string_requests,string_bytes,shared_requests,shared_bytes");
    for width in [0,128,8192,16384] {
        for length in [16,64,1024] {
            let names:Vec<String>=(0..width).map(|i|format!("{i:016}{}","x".repeat(length-16))).collect();
            let (mut owned, sr, sb)=measure(|| {
                let mut map=HashMap::with_capacity(width);
                for name in &names {map.insert(name.clone(),BindingKind::Mutable);}
                map
            });
            let (mut shared, ar, ab)=measure(|| {
                let mut map:HashMap<Arc<str>,BindingKind>=HashMap::with_capacity(width);
                for name in &names {map.insert(Arc::from(name.as_str()),BindingKind::Mutable);}
                map
            });
            println!("{width},{length},owner,{sr},{sb},{ar},{ab}");
            let (private,sr,sb)=measure(||owned.clone());
            let (view,ar,ab)=measure(||shared.clone());
            println!("{width},{length},invocation,{sr},{sb},{ar},{ab}");
            assert_eq!(private.len(),view.len());
            for name in &names {assert_eq!(private.get(name),view.get(name.as_str()));}
            if let Some(first)=names.first() {
                owned.remove(first); shared.remove(first.as_str());
                assert_eq!(private.get(first),Some(&BindingKind::Mutable));
                assert_eq!(view.get(first.as_str()),Some(&BindingKind::Mutable));
            }
            owned.insert("later".into(),BindingKind::LetImmutable);
            shared.insert(Arc::from("later"),BindingKind::LetImmutable);
            assert!(!private.contains_key("later"));assert!(!view.contains_key("later"));
        }
    }
}

