require 'csv';require 'json';require 'digest'
d=File.expand_path(__dir__)
i=JSON.parse(File.read(d+'/identity.json'));raise 'Unmeasured' unless i['status']=='component_measured'
raise 'Source drift' unless i['source_sha256']==Digest::SHA256.file(d+'/probe.rs').hexdigest
raise 'Binary drift' unless i['binary_sha256']==Digest::SHA256.file(d+'/probe').hexdigest
rows=CSV.read(d+'/results.csv',headers:true).map{|r|r.to_h.transform_values.with_index{|v,index|index==2 ? v : Integer(v)}}
expected=[0,1,3,128,129,2048,8191,8192,8193,12288,16384].product([16,17,64,65,1024],%w[owner invocation])
raise 'Coverage mismatch' unless rows.map{|r|r.values_at('width','name_length','phase')}.sort==expected.sort
raise 'Negative allocation' unless rows.all?{|r|r.reject{|k,_|k=='phase'}.values.all?{|v|v>=0}}
groups=rows.group_by{|r|r.values_at('width','name_length')}.map do |key,rs|
 owner=rs.find{|r|r['phase']=='owner'};call=rs.find{|r|r['phase']=='invocation'}
 penalty=owner['shared_bytes']-owner['string_bytes'];saving=call['string_bytes']-call['shared_bytes']
 {width:key[0],name_length:key[1],cold_byte_delta:penalty,invocation_byte_reduction:saving,invocation_request_reduction:call['string_requests']-call['shared_requests'],calls_to_amortize_cold_bytes:saving>0 ? [(penalty.to_f/saving).ceil,0].max : nil}
end
cold_regressions=groups.select{|r|r[:cold_byte_delta]>0}
result={status:'component_analysis',identity:i,source:File.read(d+'/probe.rs'),build_arguments:JSON.parse(File.read(d+'/build-lto-argv.json')),rows:rows,groups:groups,cold_regressions:cold_regressions,decision:cold_regressions.empty? ? 'No component cold-byte regression; runtime integration still unproven' : 'Unconditional replacement rejected by cold-allocation control; seek an ownership design that avoids the cold penalty',limitations:['Component map storage only, not actual Environment activation','Full runtime semantics, layout, concurrency and retention not tested','Allocation traffic only, no time or retained-memory claim']}
File.write(d+'/analysis.json',JSON.pretty_generate(result)+"\n")
puts result[:decision]
puts JSON.pretty_generate(groups.select{|x|x[:width]==8192})
